mapper.select:
SELECT 
FROM transit_stop
WHERE provider_id = #{providerId}
  AND provider_stop_id = #{providerStopId}

SELECT EXISTS (
	SELECT 1
	FROM route_direction rd
	INNER JOIN directed_stop boarding
		ON boarding.direction_id = rd.id
	   AND boarding.stop_id = #{boardingStopId}
	INNER JOIN directed_stop alighting
		ON alighting.direction_id = rd.id
	   AND alighting.stop_id = #{alightingStopId}
	INNER JOIN transit_stop terminal_stop
		ON terminal_stop.provider_id = (
			SELECT provider_id
			FROM transit_line
			WHERE id = #{lineId}
		)
	   AND terminal_stop.provider_stop_id = #{terminalProviderStopId}
	INNER JOIN directed_stop terminal
		ON terminal.direction_id = rd.id
	   AND terminal.stop_id = terminal_stop.id
	WHERE rd.line_id = #{lineId}
	  AND (
		rd.provider_direction_id = #{providerDirectionId}
		OR rd.provider_direction_id LIKE CONCAT(#{providerDirectionId}, ':%')
	  )
	  AND rd.active = TRUE
	  AND alighting.stop_sequence > boarding.stop_sequence
	  AND alighting.stop_sequence  <=  terminal.stop_sequence
)
